import sys

def find_string_between(s, t):
    n = len(s)
    for i in range(n):
        if s[i] < t[i]:
            if s[:i] + chr(ord(s[i]) + 1) + 'a' * (n - i - 1) < t:
                return s[:i] + chr(ord(s[i]) + 1) + (n - i - 1) * 'a'
    return 'No such string'

input = sys.stdin.read().strip().split()
s = input[0]
t = input[1]
print(find_string_between(s, t))
